//go:build integration

package rpc

import (
	"context"
	"github.com/WuKongIM/WuKongIM/pkg/transport/internal/core"
	"sync"
	"testing"
	"time"
)

// [DEBUG-handoff] Exercise sampling ownership through the actual pump/executor.
func TestDiagnosticLifecycleOwnership(t *testing.T) {
	s := NewService(1, func(context.Context, []byte) ([]byte, error) { return nil, nil }, core.ServiceOptions{Concurrency: 64, QueueSize: 512, MaxQueueBytes: 65536, Timeout: time.Second, QueueTimeout: time.Second}, nil)
	defer s.Stop()
	var wg sync.WaitGroup
	for i := 0; i < 16; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			done := make(chan struct{}, 1)
			finish := func() { done <- struct{}{} }
			for j := 0; j < 1024; j++ {
				ctx, cancel := context.WithTimeout(context.Background(), time.Second)
				err := s.Enqueue(Request{Context: ctx, Finish: finish})
				if err != nil {
					cancel()
					t.Error(err)
					return
				}
				<-done
				cancel()
			}
		}()
	}
	wg.Wait()
	s.Stop()
	r := DiagnosticSnapshot()
	if r.Dropped != 0 || uint64(len(r.Rows)) != r.Seen/r.Every {
		t.Fatalf("invalid sample counts: seen=%d rows=%d dropped=%d", r.Seen, len(r.Rows), r.Dropped)
	}
	for _, row := range r.Rows {
		if !row.Executed {
			t.Fatal("sample never executed")
		}
		for _, ns := range row.NS {
			if ns < 0 {
				t.Fatal("negative phase duration")
			}
		}
	}
}

